-- Only inserted into a database that already holds assets, so a fresh database stays empty for restores.
-- Open items from the retired Review Desk dashboard (24 Nov 2026): 8 unanswered questions and 1 undecided rule proposal.
INSERT OR IGNORE INTO questions (id, asset_id, question, context, options_json, created_at) SELECT 'q-SCCF-0015', 'SCCF-0015', 'Bitget (BGB): a general exchange, or derivatives-focused?', 'Bitget calls itself "the world''s largest Universal Exchange", but it is known mainly for futures and copy trading: $8.17T of derivatives volume in 2025 (spot total not found, so the share is unknown). Income reaches BGB only through buybacks and burns. Draft: Halal H2 (row 5). Strongest objection: in practice Bitget presents itself as a derivatives venue with derivatives above half, which is row 1 (Haram R2) even though BGB gets no direct income. Note: earlier records conflict; the register lists Halal H2, the old summaries Doubtful.', '["Halal H2 (general exchange; burns only)", "Doubtful D4 (row 2)", "Haram R2 (row 1: derivatives-focused)"]', '2026-11-15T16:19:11Z' WHERE EXISTS (SELECT 1 FROM assets WHERE id = 'SCCF-0015');
INSERT OR IGNORE INTO questions (id, asset_id, question, context, options_json, created_at) SELECT 'q-SCCF-0031', 'SCCF-0031', 'ether.fi (ETHFI): Doubtful D1, or Halal since staking is optional?', 'ether.fi runs a Cash card that borrows at interest through a dedicated Aave market and Liquid vaults that lend in DeFi. 25% of protocol revenue and all eETH withdrawal fees buy ETHFI, which is distributed to sETHFI stakers; the revenue split by product was not found. Draft: row 4, Doubtful D1 (a change from Halal H1). Strongest objection: holders who do not stake receive nothing, so the distribution is separable and the coin could be Halal H2 (row 5) with staking rewards ruled not halal; or, if Cash and Liquid dominate revenue, row 3 (Haram R5).', '["Doubtful D1 (row 4: share unknown)", "Halal H2 (staking optional; rewards not halal)", "Haram R5 (assume interest above a third)"]', '2026-11-15T16:35:45Z' WHERE EXISTS (SELECT 1 FROM assets WHERE id = 'SCCF-0031');
INSERT OR IGNORE INTO questions (id, asset_id, question, context, options_json, created_at) SELECT 'q-SCCF-0050', 'SCCF-0050', 'Jupiter (JUP): a general exchange, or now perps-focused?', 'Jupiter calls itself "the everything exchange". Perps earned about 54% of revenue over the last 30 days (about 43 to 45% annualised), and it also runs Predict (prediction markets), Gacha (random packs) and Lend. Half of onchain revenue, perps included, buys back JUP; nothing is paid to holders. Draft: Halal H2 (row 5). Strongest objection: with perps around half of revenue plus gambling-type products, Jupiter is in practice haram-focused, which is row 1 (Haram R2) or row 2 (Doubtful D4).', '["Halal H2 (general exchange; buybacks only)", "Doubtful D4 (row 2)", "Haram R2 (row 1: perps-focused)"]', '2026-11-15T16:35:45Z' WHERE EXISTS (SELECT 1 FROM assets WHERE id = 'SCCF-0050');
INSERT OR IGNORE INTO questions (id, asset_id, question, context, options_json, created_at) SELECT 'q-SCCF-0055', 'SCCF-0055', 'KuCoin (KCS): Doubtful D1, or does the separable bonus keep it Halal?', 'KuCoin pays a daily KCS Bonus to holders of 6+ KCS on the exchange from a share of trading fees (secondary sources say 50%), and those fees include futures and margin. The haram share was not found, so row 4 gives Doubtful D1 (a change from Halal H2). Holding KCS off the exchange earns no bonus. Strongest objection: like a separable stablecoin reward, the bonus could be ruled not halal while the coin stays Halal H2 (row 5); the tables do not say whether a separable holder payment counts as "paid straight to holders".', '["Doubtful D1 (row 4: share unknown)", "Halal H2 (bonus separable; bonus not halal)", "Haram R5 (assume derivatives above a third)"]', '2026-11-15T16:19:11Z' WHERE EXISTS (SELECT 1 FROM assets WHERE id = 'SCCF-0055');
INSERT OR IGNORE INTO questions (id, asset_id, question, context, options_json, created_at) SELECT 'q-SCCF-0063', 'SCCF-0063', 'Meteora (MET): a DEX, or a venue for meme launches?', 'Meteora describes itself as "the most composable liquidity layer for liquidity providers, launchpads and token launches on Solana". Its bonding-curve tool, used by meme launchpads, earns about 10 to 11% of revenue; most revenue is spot pool fees. It also lends idle capital through Dynamic Vaults. Income reaches MET only through buybacks. Draft: Halal H2 (DEX table row 5). Strongest objection: it is branded and seen as a venue for hype tokens (LIBRA, TRUMP, MELANIA), which is launchpad table row 1 (Haram R4).', '["Halal H2 (DEX; launch tools minor)", "Doubtful D3 (perception calls for avoidance)", "Haram R4 (launchpad row 1)"]', '2026-11-15T16:35:45Z' WHERE EXISTS (SELECT 1 FROM assets WHERE id = 'SCCF-0063');
INSERT OR IGNORE INTO questions (id, asset_id, question, context, options_json, created_at) SELECT 'q-SCCF-0100', 'SCCF-0100', 'Tron (TRX): Halal H1, or Doubtful D4 like Plasma?', 'TRON presents itself as a stablecoin settlement network and its demand comes mainly from USDT transfers. The largest DeFi activity is JustLend, an interest-based lending market governed by JST in Justin Sun''s ecosystem (about 68% of TVL), plus SunX perps. Whether TRON DAO itself runs JustLend was not found, and no source shows TRX''s value depends on it. Draft: Halal H1 (row 4), following your Algorand/Avalanche/Cosmos answer. Strongest objection: the founder''s own ecosystem runs the chain''s dominant interest product, which is close to your Plasma decision (row 2, D4). Earlier listing: Halal H1.', '["Halal H1 (coin value not tied to lending)", "Doubtful D4 (row 2, as Plasma)"]', '2026-11-15T16:19:11Z' WHERE EXISTS (SELECT 1 FROM assets WHERE id = 'SCCF-0100');
INSERT OR IGNORE INTO questions (id, asset_id, question, context, options_json, created_at) SELECT 'q-SCCF-0103', 'SCCF-0103', 'UNUS SED LEO (LEO): is Bitfinex a margin-lending platform?', 'LEO is bought back monthly with at least 27% of iFinex gross revenue, which explicitly includes margin-funding (interest) fees. Bitfinex calls itself "The Original Bitcoin Exchange" but is known for margin trading and margin funding; the revenue share from margin funding was not found. Draft: Halal H2 (row 5: buybacks only). Strongest objection: Bitfinex is seen as a margin-lending venue with that business above half or of unknown share, which is row 1 (Haram R1) even with no direct payment. The February 2021 NYAG findings (false statements) are over 5 years old and were settled without admission.', '["Halal H2 (general exchange; buybacks only)", "Doubtful D4 (row 2)", "Haram R1 (row 1: margin-lending venue)"]', '2026-11-15T16:19:11Z' WHERE EXISTS (SELECT 1 FROM assets WHERE id = 'SCCF-0103');
INSERT OR IGNORE INTO questions (id, asset_id, question, context, options_json, created_at) SELECT 'q-SCCF-0141', 'SCCF-0141', 'Lighter (LIT): confirm Haram R2 despite conflicting earlier records?', 'Lighter is a perps DEX (spot added December 2025; perps remain the core) and its fee revenue buys back and burns LIT. Row 1 gives Haram R2. The earlier list''s ruling was Haram R2 ("Presented as a perpetuals exchange"), but the register''s earlier-status column says Halal, so this may be a change. Strongest objection: none on the facts; raised only because of the conflicting earlier records and because Lighter is a large, well-known project.', '["Haram R2 (row 1: perps exchange)", "Doubtful D4 (row 2)"]', '2026-11-15T16:35:45Z' WHERE EXISTS (SELECT 1 FROM assets WHERE id = 'SCCF-0141');
INSERT OR IGNORE INTO rule_proposals (id, title, where_text, current, proposed, reason, affects) SELECT 'r-2026-11-15-native-row2', 'Native coins row 2: both limbs required', 'Chain and network tokens > Native coins, row 2', 'Is the chain neutral, but its team''s direction and the coin''s value driven by haram products (Harmony type)?', 'Is the chain neutral, but are both its team''s direction and the coin''s value driven by haram products (Harmony type)? A foundation''s marketing of interest-based products (for example tokenized bonds, private credit or Treasuries) does not meet this row on its own when the coin''s value is not shown to depend on them (decision of 15 November 2026).', 'Records your answer of 15 November 2026 on Algorand, Avalanche and Cosmos so later native coins (Hedera, XDC, Stellar and others) are read the same way.', 'None change: ALGO, AVAX, ATOM stay Halal H1; HBAR drafted under it this run' WHERE EXISTS (SELECT 1 FROM assets);
